	if (std::strcmp(s, "11") == 0) { out = OrdRejReason::UNSUPPORTED_ORDER_CHARACTERISTIC; return true; }
	if (std::strcmp(s, "12") == 0) { out = OrdRejReason::SURVEILLENCE_OPTION; return true; }
	if (std::strcmp(s, "0") == 0) { out = OrdRejReason::BROKER_CREDIT; return true; }
