enum class QuoteConditionBit : uint8_t {
	LOCKED,
	NON_FIRM,
	FAST_TRADING,
	CROSSED,
	CONSOLIDATED_BEST,
	EXCHANGE_BEST,
	CLOSED,
	OPEN,
	DEPTH,
};

using QuoteConditionMask = uint64_t;

constexpr QuoteConditionMask bit(QuoteConditionBit b) noexcept { return 1ull << (uint8_t)b; }
constexpr QuoteConditionMask set(QuoteConditionMask m, QuoteConditionBit b) noexcept { return m | bit(b); }
constexpr bool has(QuoteConditionMask m, QuoteConditionBit b) noexcept { return (m & bit(b)) != 0; }

[[nodiscard]] inline bool parse_QuoteCondition(const char *s, QuoteConditionMask &out) noexcept {
	out = 0;
	if (!s) return false;
	const char *p = s;
	while (*p) {
		if (*p == ' ') { ++p; continue; }
		switch (*p) {
			case 'E': out |= bit(QuoteConditionBit::LOCKED); break;
			case 'I': out |= bit(QuoteConditionBit::NON_FIRM); break;
			case 'H': out |= bit(QuoteConditionBit::FAST_TRADING); break;
			case 'F': out |= bit(QuoteConditionBit::CROSSED); break;
			case 'D': out |= bit(QuoteConditionBit::CONSOLIDATED_BEST); break;
			case 'C': out |= bit(QuoteConditionBit::EXCHANGE_BEST); break;
			case 'B': out |= bit(QuoteConditionBit::CLOSED); break;
			case 'A': out |= bit(QuoteConditionBit::OPEN); break;
			case 'G': out |= bit(QuoteConditionBit::DEPTH); break;
		}
		++p;
	}
	return true;
}

[[nodiscard]] inline const char *to_string_QuoteCondition(QuoteConditionMask m, char *buf, std::size_t cap) noexcept {
	std::size_t pos = 0;
	auto append = [&](const char *t){ std::size_t len=std::strlen(t); if(pos+len+1<cap){ std::memcpy(buf+pos,t,len); pos+=len; buf[pos++]=' '; } };
	if (has(m, QuoteConditionBit::LOCKED)) append("E");
	if (has(m, QuoteConditionBit::NON_FIRM)) append("I");
	if (has(m, QuoteConditionBit::FAST_TRADING)) append("H");
	if (has(m, QuoteConditionBit::CROSSED)) append("F");
	if (has(m, QuoteConditionBit::CONSOLIDATED_BEST)) append("D");
	if (has(m, QuoteConditionBit::EXCHANGE_BEST)) append("C");
	if (has(m, QuoteConditionBit::CLOSED)) append("B");
	if (has(m, QuoteConditionBit::OPEN)) append("A");
	if (has(m, QuoteConditionBit::DEPTH)) append("G");
	if (pos > 0) buf[pos-1] = '\0'; else if (cap > 0) buf[0] = '\0';
	return buf;
}

enum class TradeConditionBit : uint8_t {
	NEXT_DAY_TRADE,
	OPENED,
	SELLER,
	AVERAGE_PRICE_TRADE,
	SOLD,
	RULE155_TRADE,
	STOPPED_STOCK,
	IMBALANCE_MORE_BUYERS,
	IMBALANCE_MORE_SELLERS,
	OPENING_PRICE,
	SOLD_LAST,
	CASH,
	CASH_TRADE,
	OPENING,
	INTRADAY_TRADE_DETAIL,
	RULE127_TRADE,
	NEXT_DAY,
};

using TradeConditionMask = uint64_t;

constexpr TradeConditionMask bit(TradeConditionBit b) noexcept { return 1ull << (uint8_t)b; }
constexpr TradeConditionMask set(TradeConditionMask m, TradeConditionBit b) noexcept { return m | bit(b); }
constexpr bool has(TradeConditionMask m, TradeConditionBit b) noexcept { return (m & bit(b)) != 0; }

[[nodiscard]] inline bool parse_TradeCondition(const char *s, TradeConditionMask &out) noexcept {
	out = 0;
	if (!s) return false;
	const char *p = s;
	while (*p) {
		if (*p == ' ') { ++p; continue; }
		switch (*p) {
			case 'J': out |= bit(TradeConditionBit::NEXT_DAY_TRADE); break;
			case 'K': out |= bit(TradeConditionBit::OPENED); break;
			case 'L': out |= bit(TradeConditionBit::SELLER); break;
			case 'B': out |= bit(TradeConditionBit::AVERAGE_PRICE_TRADE); break;
			case 'M': out |= bit(TradeConditionBit::SOLD); break;
			case 'H': out |= bit(TradeConditionBit::RULE155_TRADE); break;
			case 'N': out |= bit(TradeConditionBit::STOPPED_STOCK); break;
			case 'P': out |= bit(TradeConditionBit::IMBALANCE_MORE_BUYERS); break;
			case 'Q': out |= bit(TradeConditionBit::IMBALANCE_MORE_SELLERS); break;
			case 'R': out |= bit(TradeConditionBit::OPENING_PRICE); break;
			case 'I': out |= bit(TradeConditionBit::SOLD_LAST); break;
			case 'A': out |= bit(TradeConditionBit::CASH); break;
			case 'C': out |= bit(TradeConditionBit::CASH_TRADE); break;
			case 'E': out |= bit(TradeConditionBit::OPENING); break;
			case 'F': out |= bit(TradeConditionBit::INTRADAY_TRADE_DETAIL); break;
			case 'G': out |= bit(TradeConditionBit::RULE127_TRADE); break;
			case 'D': out |= bit(TradeConditionBit::NEXT_DAY); break;
		}
		++p;
	}
	return true;
}

