	std::size_t pos = 0;
	auto append = [&](const char *t){ std::size_t len=std::strlen(t); if(pos+len+1<cap){ std::memcpy(buf+pos,t,len); pos+=len; buf[pos++]=' '; } };
	if (has(m, TradeConditionBit::NEXT_DAY_TRADE)) append("J");
