enum class OpenCloseSettleFlagBit : uint8_t {
	SESSION_OPEN,
	DELIVERY_SETTLEMENT_ENTRY,
	EXPECTED_ENTRY,
	ENTRY_FROM_PREVIOUS_BUSINESS_DAY,
	DAILY_OPEN,
};

using OpenCloseSettleFlagMask = uint64_t;

constexpr OpenCloseSettleFlagMask bit(OpenCloseSettleFlagBit b) noexcept { return 1ull << (uint8_t)b; }
constexpr OpenCloseSettleFlagMask set(OpenCloseSettleFlagMask m, OpenCloseSettleFlagBit b) noexcept { return m | bit(b); }
constexpr bool has(OpenCloseSettleFlagMask m, OpenCloseSettleFlagBit b) noexcept { return (m & bit(b)) != 0; }

[[nodiscard]] inline bool parse_OpenCloseSettleFlag(const char *s, OpenCloseSettleFlagMask &out) noexcept {
	out = 0;
	if (!s) return false;
	const char *p = s;
	while (*p) {
		if (*p == ' ') { ++p; continue; }
		switch (*p) {
			case '1': out |= bit(OpenCloseSettleFlagBit::SESSION_OPEN); break;
			case '2': out |= bit(OpenCloseSettleFlagBit::DELIVERY_SETTLEMENT_ENTRY); break;
			case '3': out |= bit(OpenCloseSettleFlagBit::EXPECTED_ENTRY); break;
			case '4': out |= bit(OpenCloseSettleFlagBit::ENTRY_FROM_PREVIOUS_BUSINESS_DAY); break;
			case '0': out |= bit(OpenCloseSettleFlagBit::DAILY_OPEN); break;
		}
		++p;
	}
	return true;
}

[[nodiscard]] inline const char *to_string_OpenCloseSettleFlag(OpenCloseSettleFlagMask m, char *buf, std::size_t cap) noexcept {
	std::size_t pos = 0;
	auto append = [&](const char *t){ std::size_t len=std::strlen(t); if(pos+len+1<cap){ std::memcpy(buf+pos,t,len); pos+=len; buf[pos++]=' '; } };
	if (has(m, OpenCloseSettleFlagBit::SESSION_OPEN)) append("1");
	if (has(m, OpenCloseSettleFlagBit::DELIVERY_SETTLEMENT_ENTRY)) append("2");
	if (has(m, OpenCloseSettleFlagBit::EXPECTED_ENTRY)) append("3");
	if (has(m, OpenCloseSettleFlagBit::ENTRY_FROM_PREVIOUS_BUSINESS_DAY)) append("4");
	if (has(m, OpenCloseSettleFlagBit::DAILY_OPEN)) append("0");
	if (pos > 0) buf[pos-1] = '\0'; else if (cap > 0) buf[0] = '\0';
	return buf;
}

