	if (!s) return false;
	if (std::strcmp(s, "12") == 0) { out = SessionRejectReason::XML_VALIDATION_ERROR; return true; }
	if (std::strcmp(s, "17") == 0) { out = SessionRejectReason::NON; return true; }
	if (std::strcmp(s, "16") == 0) { out = SessionRejectReason::INCORRECT_NUM_IN_GROUP_COUNT_FOR_REPEATING_GROUP; return true; }
	if (std::strcmp(s, "15") == 0) { out = SessionRejectReason::REPEATING_GROUP_FIELDS_OUT_OF_ORDER; return true; }
	if (std::strcmp(s, "14") == 0) { out = SessionRejectReason::TAG_SPECIFIED_OUT_OF_REQUIRED_ORDER; return true; }
	if (std::strcmp(s, "11") == 0) { out = SessionRejectReason::INVALID_MSG_TYPE; return true; }
	if (std::strcmp(s, "0") == 0) { out = SessionRejectReason::INVALID_TAG_NUMBER; return true; }
	if (std::strcmp(s, "9") == 0) { out = SessionRejectReason::COMP_ID_PROBLEM; return true; }
	if (std::strcmp(s, "8") == 0) { out = SessionRejectReason::SIGNATURE_PROBLEM; return true; }
	if (std::strcmp(s, "7") == 0) { out = SessionRejectReason::DECRYPTION_PROBLEM; return true; }
	if (std::strcmp(s, "6") == 0) { out = SessionRejectReason::INCORRECT_DATA_FORMAT_FOR_VALUE; return true; }
	if (std::strcmp(s, "5") == 0) { out = SessionRejectReason::VALUE_IS_INCORRECT; return true; }
	if (std::strcmp(s, "4") == 0) { out = SessionRejectReason::TAG_SPECIFIED_WITHOUT_A_VALUE; return true; }
	if (std::strcmp(s, "3") == 0) { out = SessionRejectReason::UNDEFINED_TAG; return true; }
	if (std::strcmp(s, "10") == 0) { out = SessionRejectReason::SENDING_TIME_ACCURACY_PROBLEM; return true; }
	if (std::strcmp(s, "13") == 0) { out = SessionRejectReason::TAG_APPEARS_MORE_THAN_ONCE; return true; }
	if (std::strcmp(s, "2") == 0) { out = SessionRejectReason::TAG_NOT_DEFINED_FOR_THIS_MESSAGE_TYPE; return true; }
	if (std::strcmp(s, "1") == 0) { out = SessionRejectReason::REQUIRED_TAG_MISSING; return true; }
